/* =====================================================================
   PSU-LASC — ลงทะเบียนสัตวแพทย์ผ่าน LINE Official Account
   สัตวแพทย์พิมพ์ "ลงทะเบียน ชื่อ-สกุล" (หรือพิมพ์ "ลงทะเบียน" ในกลุ่ม LINE ที่เชิญบัญชีไว้)
   → บันทึกคำขอไว้ที่ {ROOT}/vetRequests/{lineId} → เจ้าหน้าที่กด「➕ เพิ่มเป็นผู้รับแจ้ง」ในระบบ
   คำขอทุกคำขอต้องผ่านการอนุมัติของเจ้าหน้าที่ก่อนจะได้รับแจ้งเตือนจริง

   ใช้ Environment variables ชุดเดียวกับ workflow แจ้งเหตุ:
     LASC_FB_DB_URL · LASC_FB_DB_SECRET · LASC_FB_ROOT · LASC_LINE_TOKEN
   ===================================================================== */
/* ── ถ้า n8n อ่าน Environment variables ไม่ได้ (เช่น n8n Cloud) ให้กรอกค่าตรงนี้แทน ──
   ต้องเป็นค่าชุดเดียวกับ workflow「แจ้งทีมสัตวแพทย์」                                   */
const CFG = {
  LASC_FB_DB_URL:    '',
  LASC_FB_DB_SECRET: '',
  LASC_FB_ROOT:      'animalReport',
  LASC_LINE_TOKEN:   ''
};
const envv = (k) => {
  try { if (typeof $env !== 'undefined' && $env[k]) return String($env[k]); } catch (e) {}
  return String(CFG[k] || '');
};
const ENV = {
  db:     envv('LASC_FB_DB_URL').replace(/\/+$/, ''),
  secret: envv('LASC_FB_DB_SECRET'),
  root:   (envv('LASC_FB_ROOT') || 'animalReport').replace(/^\/+|\/+$/g, ''),
  line:   envv('LASC_LINE_TOKEN')
};
const http = (opts) => this.helpers.httpRequest(Object.assign({ json: true, timeout: 15000 }, opts));
const fbUrl = (path) => `${ENV.db}/${ENV.root}/${path}.json?auth=${encodeURIComponent(ENV.secret)}`;
const lineApi = (method, path, body) => http({
  method, url: 'https://api.line.me' + path, headers: { Authorization: 'Bearer ' + ENV.line }, body
});
const reply = (token, text) => token
  ? lineApi('POST', '/v2/bot/message/reply', { replyToken: token, messages: [{ type: 'text', text }] }).catch(() => {})
  : Promise.resolve();

const HELP = 'ระบบแจ้งเหตุสัตว์ทดลอง PSU:LASC\n' +
  '• พิมพ์ "ลงทะเบียน ชื่อ-สกุล" เพื่อขอรับแจ้งเหตุฉุกเฉิน/ปัญหาสุขภาพสัตว์ทาง LINE\n' +
  '• ในกลุ่มสัตวแพทย์ พิมพ์ "ลงทะเบียน" เพื่อให้ทั้งกลุ่มรับแจ้ง\n' +
  '• พิมพ์ "ยกเลิก" เพื่อแจ้งขอหยุดรับแจ้ง';

const events = (($input.first().json.body || {}).events) || [];
const done = [];
if (!ENV.db || !ENV.secret || !ENV.line) return [{ json: { ok: false, error: 'ตั้งค่า LASC_FB_DB_URL / LASC_FB_DB_SECRET / LASC_LINE_TOKEN ไม่ครบ' } }];

for (const ev of events) {
  const src = ev.source || {};
  const lineId = src.groupId || src.roomId || src.userId || '';
  const type = src.groupId || src.roomId ? 'group' : 'user';
  if (!/^[UCR][0-9a-f]{32}$/.test(lineId)) continue;

  if (ev.type === 'follow' || ev.type === 'join') { await reply(ev.replyToken, 'สวัสดีครับ 🙏\n' + HELP); done.push(ev.type); continue; }
  if (ev.type !== 'message' || !ev.message || ev.message.type !== 'text') continue;

  const text = String(ev.message.text || '').trim();
  const m = text.match(/^(ลงทะเบียน|register)\s*(.*)$/i);
  if (m) {
    let displayName = '';
    try {
      if (type === 'user') displayName = (await lineApi('GET', '/v2/bot/profile/' + lineId)).displayName || '';
      else if (src.groupId) displayName = (await lineApi('GET', '/v2/bot/group/' + lineId + '/summary')).groupName || '';
    } catch (e) {}
    let byName = '';
    if (type === 'group' && src.userId) {
      try { byName = (await lineApi('GET', `/v2/bot/group/${lineId}/member/${src.userId}`)).displayName || ''; } catch (e) {}
    }
    await http({ method: 'PUT', url: fbUrl('vetRequests/' + lineId), body: {
      lineId, type, displayName: displayName.slice(0, 100), name: m[2].trim().slice(0, 100),
      requestedBy: byName.slice(0, 100), at: new Date().toISOString()
    } });
    await reply(ev.replyToken, `✅ รับคำขอรับแจ้งเหตุแล้ว${type === 'group' ? ' (ทั้งกลุ่ม)' : ''}\n` +
      'รอเจ้าหน้าที่ศูนย์สัตว์ทดลองอนุมัติในระบบ — เมื่ออนุมัติแล้วจะเริ่มได้รับแจ้งเตือนทันที');
    done.push('register');
    continue;
  }
  if (/^(ยกเลิก|unregister)$/i.test(text)) {
    await http({ method: 'PUT', url: fbUrl('vetRequests/' + lineId), body: {
      lineId, type, displayName: '', name: '⛔ ขอยกเลิกการรับแจ้ง', at: new Date().toISOString()
    } });
    await reply(ev.replyToken, 'ส่งคำขอยกเลิกให้เจ้าหน้าที่แล้ว — เจ้าหน้าที่จะปิดการแจ้งเตือนของท่านในระบบ');
    done.push('unregister');
    continue;
  }
  if (type === 'user' && /^(help|ช่วยเหลือ|วิธีใช้)$/i.test(text)) { await reply(ev.replyToken, HELP); done.push('help'); }
}
return [{ json: { ok: true, handled: done } }];
